func TestORMGenerateProducesDeterministicInspectableCode(t *testing.T) {
	directory := writeORMProject(t, validORMModels)
	t.Chdir(directory)
	var output bytes.Buffer
	if err := Run([]string{"orm:generate"}, &output, &output); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(output.String(), "created "+generatedORMPath) {
		t.Fatalf("generation output = %q", output.String())
	}
	artifact := readORMArtifact(t)
	for _, expected := range []string{
		"// Code generated by GoForge. DO NOT EDIT.",
		"var IssueMapper = orm.MustMapper[Issue]",
		"var IssueTable = orm.MustTable(\"issues\", IssueMapper)",
		"orm.Column[Issue, int64]",
		"type IssueCreateInput struct",
		"Name      string",
		"Note      orm.Field[*string]",
		"Published orm.Field[bool]",
		"type IssueChanges struct",
		"func (store Store) Issues() IssueQuery",
		"additional ...orm.Assignment[Issue]",
		"func IssueOwnerRelation(options orm.RelationOptions) orm.BelongsTo[Issue, User, int64]",
		"var IssueRelations = struct",
		"func (query IssueQuery) LoadOwner(ctx context.Context",
	} {
		if !strings.Contains(artifact, expected) {
			t.Errorf("generated ORM is missing %q:\n%s", expected, artifact)
		}
	}
	for _, forbidden := range []string{"model.Owner", "belongs_to", "reflect"} {
		if strings.Contains(artifact, forbidden) {
			t.Errorf("generated ORM unexpectedly contains %q", forbidden)
		}
	}
	createStart := strings.Index(artifact, "type IssueCreateInput struct")
	createEnd := strings.Index(artifact[createStart:], "}\n") + createStart
	create := artifact[createStart:createEnd]
	for _, protected := range []string{"ID ", "UserID ", "CreatedAt "} {
		if strings.Contains(create, protected) {
			t.Errorf("create input exposes protected/generated field %q:\n%s", protected, create)
		}
	}
	if _, err := parser.ParseFile(token.NewFileSet(), generatedORMPath, artifact, parser.AllErrors); err != nil {
		t.Fatalf("generated artifact is not Go: %v", err)
	}

	first := append([]byte(nil), []byte(artifact)...)
	writes := 0
	if err := generateORMWith(false, &output, renderORMArtifact, func(string, []byte) error {
		writes++
		return errors.New("identical output should not be written")
	}); err != nil {
		t.Fatal(err)
	}
	if writes != 0 || !bytes.Equal(first, []byte(readORMArtifact(t))) {
		t.Fatalf("identical generation wrote %d times or changed output", writes)
	}

	var check bytes.Buffer
	if err := Run([]string{"orm:generate", "--check"}, &check, &check); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(check.String(), generatedORMPath+" is current") {
		t.Fatalf("check output = %q", check.String())
	}
}

func TestORMGenerateCompilesRelationshipRichModelsAndBudgetsQueries(t *testing.T) {
	root := projectRoot(t)
	directory := writeORMProject(t, relationshipRichORMModels)
	t.Chdir(directory)
	var output bytes.Buffer
	if err := generateORM(false, &output); err != nil {
		t.Fatal(err)
	}
	artifact := readORMArtifact(t)
	for _, expected := range []string{
		"orm.BelongsTo[Post, User, int64]",
		"orm.HasOne[User, Profile, int64]",
		"orm.HasMany[User, Post, int64]",
		"orm.ManyToMany[Post, Tag, int64, int64]",
		"if parent.AuthorID == nil",
		"if target.UserID == nil",
		"func (query PostQuery) AttachTags",
		"func (query PostQuery) DetachTags",
	} {
		if !strings.Contains(artifact, expected) {
			t.Errorf("generated relationships are missing %q:\n%s", expected, artifact)
		}
	}

	module := "module example.com/generated-relations\n\ngo 1.25\n\nrequire github.com/ShanilKoshitha/goforge v0.0.0\n\nreplace github.com/ShanilKoshitha/goforge => " + filepath.ToSlash(root) + "\n"
	if err := os.WriteFile("go.mod", []byte(module), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join("internal", "models", "zz_orm_relations_gen_test.go"), []byte(generatedORMRelationshipTest), 0o644); err != nil {
		t.Fatal(err)
	}
	command := exec.Command("go", "test", "-mod=mod", "./internal/models")
	command.Dir = directory
	command.Env = append(os.Environ(),
		"GOCACHE="+filepath.Join(root, ".cache", "go-build"),
		"GOMODCACHE="+filepath.Join(root, ".cache", "go-mod"),
		"GOWORK=off",
	)
	if result, err := command.CombinedOutput(); err != nil {
		t.Fatalf("generated relationships do not compile and execute: %v\n%s\n%s", err, result, artifact)
	}
}

func TestORMGenerateCheckDetectsMissingAndStaleWithoutWriting(t *testing.T) {
	directory := writeORMProject(t, validORMModels)
	t.Chdir(directory)
	var output bytes.Buffer
	if err := Run([]string{"orm:generate", "--check"}, &output, &output); err == nil || !strings.Contains(err.Error(), "generated ORM is missing") {
		t.Fatalf("missing check error = %v", err)
	}
	if _, err := os.Stat(filepath.FromSlash(generatedORMPath)); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("check mode created output: %v", err)
	}
	if err := Run([]string{"orm:generate"}, &output, &output); err != nil {
		t.Fatal(err)
	}
	before := readORMArtifact(t)
	modelPath := filepath.Join("internal", "models", "z_issue.go")
	changed := strings.Replace(validORMModels["z_issue.go"], "\tOwner     User", "\tPriority  int64 `forge:\"required,default=0\"`\n\tOwner     User", 1)
	if err := os.WriteFile(modelPath, []byte(changed), 0o644); err != nil {
		t.Fatal(err)
	}
	writes := 0
	err := generateORMWith(true, &output, renderORMArtifact, func(string, []byte) error {
		writes++
		return nil
	})
	if err == nil || !strings.Contains(err.Error(), "generated ORM is stale") {
		t.Fatalf("stale check error = %v", err)
	}
	if writes != 0 || readORMArtifact(t) != before {
		t.Fatal("stale check wrote or changed the last generated artifact")
	}
}

func TestORMGenerateRetainsLastGoodArtifactOnFailures(t *testing.T) {
	directory := writeORMProject(t, validORMModels)
	t.Chdir(directory)
	var output bytes.Buffer
	if err := generateORM(false, &output); err != nil {
		t.Fatal(err)
	}
	before := readORMArtifact(t)
	modelPath := filepath.Join("internal", "models", "z_issue.go")
	if err := os.WriteFile(modelPath, []byte("package models\ntype Broken struct {\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := generateORM(false, &output); err == nil || !strings.Contains(err.Error(), "parse ORM models") {
		t.Fatalf("parse error = %v", err)
	}
	if readORMArtifact(t) != before {
		t.Fatal("parse failure changed last good artifact")
	}
	if err := os.WriteFile(modelPath, []byte(validORMModels["z_issue.go"]), 0o644); err != nil {
		t.Fatal(err)
	}

	for _, failure := range []struct {
		name   string
		render ormArtifactRenderer
		write  ormArtifactWriter
	}{
		{
			name: "render or format",
			render: func(modelSchema) (string, error) {
				return "", errors.New("injected format failure")
			},
			write: func(string, []byte) error { t.Fatal("writer called after render failure"); return nil },
		},
		{
			name:   "publication",
			render: func(modelSchema) (string, error) { return before + "// stale\n", nil },
			write:  func(string, []byte) error { return errors.New("injected write failure") },
		},
	} {
		t.Run(failure.name, func(t *testing.T) {
			if err := generateORMWith(false, &output, failure.render, failure.write); err == nil {
				t.Fatal("expected injected failure")
			}
			if readORMArtifact(t) != before {
				t.Fatal("failure changed last good artifact")
			}
		})
	}
}

func TestORMGenerateReplacesCorruptSelfIdentifiedArtifact(t *testing.T) {
	directory := writeORMProject(t, validORMModels)
	t.Chdir(directory)
	path := filepath.FromSlash(generatedORMPath)
	corrupt := "// Code generated by GoForge. DO NOT EDIT.\npackage models\nthis is not Go\n"
	if err := os.WriteFile(path, []byte(corrupt), 0o644); err != nil {
		t.Fatal(err)
	}
	var output bytes.Buffer
	if err := generateORM(false, &output); err != nil {
		t.Fatal(err)
	}
	artifact := readORMArtifact(t)
	if artifact == corrupt || !strings.Contains(artifact, "var IssueMapper") {
		t.Fatal("generator did not replace its corrupt self-identified artifact")
	}
}

func TestORMGenerateRejectsDeclarationCollisionsBeforeWriting(t *testing.T) {
	tests := []struct {
		name   string
		source string
		want   string
	}{
		{
			name: "store",
			source: `package models
type Store struct { ID int64 ` + "`forge:\"primary,required\"`" + ` }
`,
			want: "generated declaration Store",
		},
		{
			name: "derived declaration",
			source: `package models
type User struct { ID int64 ` + "`forge:\"primary,required\"`" + ` }
type UserMapper = string
`,
			want: "generated declaration UserMapper",
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			directory := writeORMProject(t, map[string]string{"model.go": test.source})
			t.Chdir(directory)
			var output bytes.Buffer
			err := generateORM(false, &output)
			if err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("collision error = %v", err)
			}
			if _, err := os.Stat(filepath.FromSlash(generatedORMPath)); !errors.Is(err, os.ErrNotExist) {
				t.Fatalf("collision generated output: %v", err)
			}
		})
	}
}

