func TestORMGenerateCLIUsage(t *testing.T) {
	var output bytes.Buffer
	printHelp(&output)
	if !strings.Contains(output.String(), "forge orm:generate [--check]") {
		t.Fatalf("help omits ORM generator:\n%s", output.String())
	}
	directory := writeORMProject(t, validORMModels)
	t.Chdir(directory)
	if err := Run([]string{"orm:generate", "--write"}, &output, &output); err == nil || err.Error() != "usage: forge orm:generate [--check]" {
		t.Fatalf("invalid arguments error = %v", err)
	}
}

func TestORMGenerateRequiresSupportedProjectFormatBeforeWriting(t *testing.T) {
	for _, test := range []struct {
		version string
		want    string
	}{
		{version: "3", want: "upgrade the project to format 4"},
		{version: "10", want: "newer than this CLI supports"},
	} {
		t.Run(test.version, func(t *testing.T) {
			directory := t.TempDir()
			t.Chdir(directory)
			if err := os.WriteFile("forge.yaml", []byte("version: "+test.version+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			var output bytes.Buffer
			err := Run([]string{"orm:generate"}, &output, &output)
			if err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("format %s error = %v", test.version, err)
			}
			if _, err := os.Stat(filepath.FromSlash(generatedORMPath)); !errors.Is(err, os.ErrNotExist) {
				t.Fatalf("format refusal wrote generated ORM: %v", err)
			}
		})
	}
}

func writeORMProject(t *testing.T, sources map[string]string) string {
	t.Helper()
	directory := t.TempDir()
	if err := os.WriteFile(filepath.Join(directory, "forge.yaml"), []byte("version: 4\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	models := filepath.Join(directory, "internal", "models")
	if err := os.MkdirAll(models, 0o755); err != nil {
		t.Fatal(err)
	}
	for name, source := range sources {
		if err := os.WriteFile(filepath.Join(models, name), []byte(source), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return directory
}

func readORMArtifact(t *testing.T) string {
	t.Helper()
	contents, err := os.ReadFile(filepath.FromSlash(generatedORMPath))
	if err != nil {
		t.Fatal(err)
	}
	return string(contents)
}

