const generatedORMRelationshipTest = `package models

import (
	"reflect"
	"strings"
	"testing"

	forgeorm "github.com/ShanilKoshitha/goforge/orm"
)

func TestGeneratedRelationshipDescriptorsAndBudgets(t *testing.T) {
	one, two, three := int64(1), int64(2), int64(3)
	posts := []Post{{ID: 1, AuthorID: &one}, {ID: 2, AuthorID: nil}, {ID: 3, AuthorID: &two}, {ID: 4, AuthorID: &one}}
	belongsStatements, err := PostAuthorRelation(forgeorm.RelationOptions{ParameterLimit: 2}).Build(posts, forgeorm.Select(UserTable))
	if err != nil { t.Fatal(err) }
	if len(belongsStatements) != 1 || !reflect.DeepEqual(belongsStatements[0].Args(), []any{int64(1), int64(2)}) {
		t.Fatalf("nullable belongs-to keys were not normalized/deduplicated: %#v", belongsStatements)
	}

	users := []User{{ID: one}, {ID: two}, {ID: three}}
	postsScope := forgeorm.Select(PostTable).Where(PostColumns.Title.Eq("visible"))
	hasManyStatements, err := UserPostsRelation(forgeorm.RelationOptions{ParameterLimit: 2}).Build(users, postsScope)
	if err != nil { t.Fatal(err) }
	if len(hasManyStatements) != 3 {
		t.Fatalf("has-many statements = %d, want three one-key batches", len(hasManyStatements))
	}
	for index, statement := range hasManyStatements {
		want := []any{"visible", int64(index + 1)}
		if !reflect.DeepEqual(statement.Args(), want) || !strings.Contains(statement.SQL(), ` + "`\"posts\".\"title\" = $1`" + `) {
			t.Fatalf("scoped has-many statement %d: %s %#v", index, statement.SQL(), statement.Args())
		}
	}

	hasOneStatements, err := UserProfileRelation(forgeorm.RelationOptions{ParameterLimit: 2}).Build(users, forgeorm.Select(ProfileTable))
	if err != nil || len(hasOneStatements) != 2 {
		t.Fatalf("nullable has-one target key did not batch: %d %v", len(hasOneStatements), err)
	}

	tagsScope := forgeorm.Select(TagTable).Where(TagColumns.Name.Eq("go"))
	manyStatements, err := PostTagsRelation(forgeorm.RelationOptions{ParameterLimit: 2}).Build(posts[:3], tagsScope)
	if err != nil || len(manyStatements) != 3 {
		t.Fatalf("many-to-many scoped statements = %d, error %v", len(manyStatements), err)
	}
	attach, err := PostRelations.Tags.BuildAttach(7, 9)
	if err != nil || !strings.Contains(attach.SQL(), ` + "`ON CONFLICT (\"post_id\", \"tag_id\") DO NOTHING`" + `) {
		t.Fatalf("attach statement: %s %v", attach.SQL(), err)
	}
	detach, err := PostRelations.Tags.BuildDetach(7, 9)
	if err != nil || !strings.Contains(detach.SQL(), ` + "`WHERE \"post_id\" = $1 AND \"tag_id\" = $2`" + `) {
		t.Fatalf("detach statement: %s %v", detach.SQL(), err)
	}
}
`

const generatedORMExecutionTest = `package models

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"io"
	"reflect"
	"sync"
	"testing"
	"time"

	forgeorm "github.com/ShanilKoshitha/goforge/orm"
)

var registerModelDriver sync.Once

func TestGeneratedStoreExecutesThroughDBAndTx(t *testing.T) {
	registerModelDriver.Do(func() { sql.Register("goforge-generated-model-test", modelDriver{}) })
	db, err := sql.Open("goforge-generated-model-test", "")
	if err != nil { t.Fatal(err) }
	defer db.Close()
	store := NewStore(db)
	issues := store.Issues()
	nullInsert, err := issues.Create(IssueCreateInput{Name: "created", Note: forgeorm.Null[*string]()}, IssueColumns.UserID.Set(7)).Build()
	if err != nil { t.Fatal(err) }
	if nullInsert.SQL() != ` + "`INSERT INTO \"issues\" (\"name\", \"note\", \"user_id\") VALUES ($1, $2, $3) RETURNING \"issues\".\"id\", \"issues\".\"user_id\", \"issues\".\"name\", \"issues\".\"note\", \"issues\".\"published\", \"issues\".\"created_at\"`" + ` || !reflect.DeepEqual(nullInsert.Args(), []any{"created", nil, int64(7)}) { t.Fatalf("null/default insert: %s %#v", nullInsert.SQL(), nullInsert.Args()) }
	valueInsert, err := issues.Create(IssueCreateInput{Name: "created", Published: forgeorm.Value(true)}, IssueColumns.UserID.Set(7)).Build()
	if err != nil { t.Fatal(err) }
	if valueInsert.SQL() != ` + "`INSERT INTO \"issues\" (\"name\", \"published\", \"user_id\") VALUES ($1, $2, $3) RETURNING \"issues\".\"id\", \"issues\".\"user_id\", \"issues\".\"name\", \"issues\".\"note\", \"issues\".\"published\", \"issues\".\"created_at\"`" + ` || !reflect.DeepEqual(valueInsert.Args(), []any{"created", true, int64(7)}) { t.Fatalf("value/default insert: %s %#v", valueInsert.SQL(), valueInsert.Args()) }
	update, err := issues.Update(IssueChanges{Name: forgeorm.Value("changed"), Note: forgeorm.Null[*string]()} ).Where(IssueColumns.ID.Eq(11), IssueColumns.UserID.Eq(7)).Build()
	if err != nil { t.Fatal(err) }
	if update.SQL() != ` + "`UPDATE \"issues\" SET \"name\" = $1, \"note\" = $2 WHERE \"issues\".\"id\" = $3 AND \"issues\".\"user_id\" = $4`" + ` || !reflect.DeepEqual(update.Args(), []any{"changed", nil, int64(11), int64(7)}) { t.Fatalf("partial update: %s %#v", update.SQL(), update.Args()) }
	fromDB, err := issues.Select().First(context.Background(), issues.Executor)
	if err != nil || fromDB.ID != 11 || fromDB.UserID != 7 || fromDB.Name != "mapped" { t.Fatalf("db mapping: %+v %v", fromDB, err) }
	tx, err := db.BeginTx(context.Background(), nil)
	if err != nil { t.Fatal(err) }
	defer tx.Rollback()
	transactional := NewStore(tx).Issues()
	fromTx, err := transactional.Create(IssueCreateInput{Name: "created"}, IssueColumns.UserID.Set(7)).One(context.Background(), transactional.Executor)
	if err != nil || fromTx.ID != 11 || fromTx.UserID != 7 { t.Fatalf("tx mapping: %+v %v", fromTx, err) }
}

type modelDriver struct{}
func (modelDriver) Open(string) (driver.Conn, error) { return &modelConnection{}, nil }

type modelConnection struct{}
func (*modelConnection) Prepare(string) (driver.Stmt, error) { return nil, driver.ErrSkip }
func (*modelConnection) Close() error { return nil }
func (*modelConnection) Begin() (driver.Tx, error) { return modelTransaction{}, nil }
func (*modelConnection) QueryContext(context.Context, string, []driver.NamedValue) (driver.Rows, error) {
	return &modelRows{}, nil
}

type modelTransaction struct{}
func (modelTransaction) Commit() error { return nil }
func (modelTransaction) Rollback() error { return nil }

type modelRows struct{ sent bool }
func (*modelRows) Columns() []string { return []string{"id", "user_id", "name", "note", "published", "created_at"} }
func (*modelRows) Close() error { return nil }
func (rows *modelRows) Next(values []driver.Value) error {
	if rows.sent { return io.EOF }
	rows.sent = true
	copy(values, []driver.Value{int64(11), int64(7), "mapped", nil, false, time.Unix(1, 0)})
	return nil
}
`
